describe('Native Verifier startup receipts', () => {
  let root: string;
  let paths: NativeProjectPaths;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-verifier-start-'));
    await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
    paths = await nativeProjectPaths(root, 'docs');
    await ensureNativeDirectories(paths);
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await fs.rm(root, { recursive: true, force: true });
  });

  async function dispatchVerifier(name: string) {
    await createNativePortableChange({ paths, name, language: 'en' });
    await fs.writeFile(
      path.join(paths.changesDir, name, 'brief.md'),
      '# Acceptance examples\n- Startup receipts stay observable.\n',
    );
    let state = await confirmNativePortableShape({ paths, name });
    const runner = createNativeRunnerChannel();
    state = await submitNativePortableBuilderCandidate({
      paths,
      name: state.name,
      input: {
        identity: runner.captureExecutionIdentity({
          identityProvider: NATIVE_SKILL_COORDINATION,
          executionRef: `${NATIVE_SKILL_COORDINATION}:builder:test-builder`,
        }),
        candidateId: 'candidate',
        summary: 'Built.',
        addressedAcceptanceIds: state.acceptance.map(({ id }) => id),
        acceptanceReview: fixtureAcceptanceReview(state.acceptance.map(({ id }) => id)),
        review: null,
      },
    });
    return applyNativeRunnerInput({
      paths,
      name,
      input: { kind: 'dispatch-verifier', checks: [] },
      maxVerifyFailures: 5,
    });
  }

  it('keeps a dispatched attempt unconfirmed until the Verifier reports startup', async () => {
    const dispatched = await dispatchVerifier('receipt-observable');
    const verifierExecutionRef = dispatched.verifierDispatch!.verifierExecutionRef;
    expect(dispatched.state.verifier_action).toMatchObject({
      type: 'handoff',
      ref: 'native-verifier',
      status: 'pending',
      attempt: 1,
    });

    const before = await inspectNativePortableStatus({ paths, name: 'receipt-observable' });
    expect(before.localExecution.verifierStartup).toMatchObject({
      attempt: 1,
      confirmation: 'unconfirmed',
      confirmedAt: null,
    });
    expect(before.localExecution.verifierStartup!.registeredAt).toBeTruthy();
    expect(before.continuation.userCommunication.agentInstruction).toContain(
      'Check whether the host accepted the startup call',
    );
    expect(dispatched.continuation.userCommunication.agentInstruction).toContain(
      'Check whether the host accepted the startup call',
    );
    expect(before.continuation.requiresUserDecision).toBe(false);
    const resumed = JSON.parse(
      (
        await runNativeCli([
          'next',
          'receipt-observable',
          '--summary',
          'Resume verification.',
          '--project-root',
          root,
          '--json',
        ])
      ).stdout!,
    );
    expect(resumed.exitCode).toBe(0);
    expect(resumed.data.continuation.userCommunication.agentInstruction).toContain(
      'Check whether the host accepted the startup call',
    );

    const confirmed = await applyNativeRunnerInput({
      paths,
      name: 'receipt-observable',
      input: {
        kind: 'verifier-started',
        candidateId: dispatched.state.builder_handoff!.candidate_id,
        verifierExecutionRef,
      },
      maxVerifyFailures: 5,
    });
    expect(confirmed.state.loop.next_action).toBe('await-verifier-result');
    expect(confirmed.state.verifier_action).toMatchObject({
      status: 'running',
      claim: { token: verifierExecutionRef },
    });

    const after = await inspectNativePortableStatus({ paths, name: 'receipt-observable' });
    expect(after.localExecution.verifierStartup).toMatchObject({
      attempt: 1,
      confirmation: 'confirmed',
    });
    expect(after.localExecution.verifierStartup!.confirmedAt).toBeTruthy();
    expect(after.continuation.userCommunication.agentInstruction).toContain(
      'The Verifier has confirmed startup',
    );
    expect(confirmed.continuation.userCommunication.agentInstruction).toContain(
      'The Verifier has confirmed startup',
    );
    expect(after.continuation.userCommunication.agentInstruction).not.toContain(
      'Check whether the host accepted the startup call',
    );
    const overlay = await readNativeLocalExecution(
      nativeLocalExecutionFile(paths, 'receipt-observable'),
    );
    expect(overlay?.execution?.verifierStartedAt).toBe(
      after.localExecution.verifierStartup!.confirmedAt,
    );
    expect(nativeVerifierStartupConfirmationForState(confirmed.state, overlay)).toBe('confirmed');
    expect(nativeVerifierStartupConfirmationForState(confirmed.state, null)).toBe('confirmed');
    expect(
      nativeVerifierStartupConfirmationForState(confirmed.state, {
        ...overlay!,
        candidateId: 'stale-candidate',
      }),
    ).toBe('confirmed');
    expect(
      nativeVerifierStartupConfirmationForState(confirmed.state, {
        ...overlay!,
        basedOnStateVersion: confirmed.state.state_version - 1,
      }),
    ).toBe('confirmed');
    const resumedConfirmed = JSON.parse(
      (
        await runNativeCli([
          'next',
          'receipt-observable',
          '--summary',
          'Resume verification.',
          '--project-root',
          root,
          '--json',
        ])
      ).stdout!,
    );
    expect(resumedConfirmed.exitCode).toBe(0);
    expect(resumedConfirmed.data.continuation.userCommunication.agentInstruction).toContain(
      'The Verifier has confirmed startup',
    );

    const repeated = await applyNativeRunnerInput({
      paths,
      name: 'receipt-observable',
      input: {
        kind: 'verifier-started',
        candidateId: dispatched.state.builder_handoff!.candidate_id,
        verifierExecutionRef,
      },
      maxVerifyFailures: 5,
    });
    expect(repeated.state.state_version).toBe(confirmed.state.state_version);
    const afterRepeat = await inspectNativePortableStatus({ paths, name: 'receipt-observable' });
    expect(afterRepeat.localExecution.verifierStartup!.confirmedAt).toBe(
      after.localExecution.verifierStartup!.confirmedAt,
    );
  });

  it('keeps the dispatched identity when the machine overlay is lost', async () => {
    const dispatched = await dispatchVerifier('receipt-overlay-lost');
    await fs.unlink(nativeLocalExecutionFile(paths, 'receipt-overlay-lost'));
    const recovered = await recoverNativePortableChange({ paths, name: 'receipt-overlay-lost' });
    expect(recovered).toMatchObject({ action: 'await-user', reason: 'execution-active' });
    expect(recovered.state.verifier_action?.id).toBe(dispatched.state.verifier_action?.id);
    const status = await inspectNativePortableStatus({ paths, name: 'receipt-overlay-lost' });
    expect(status.continuation.action).toBe('await-verifier');
    expect(JSON.stringify(status.continuation)).toContain(
      dispatched.verifierDispatch!.verifierExecutionRef,
    );
    const state = recovered.state;
    const failed = await applyNativeRunnerInput({
      paths,
      name: state.name,
      maxVerifyFailures: 5,
      input: {
        kind: 'verifier-execution-error',
        summary: 'The host confirmed that the task was lost.',
        stateVersion: state.state_version,
        iteration: state.loop.iteration,
        attempt: state.loop.attempt,
        verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
      },
    });
    expect(failed.state.verifier_action?.status).toBe('failed');
    expect(failed.state.loop.execution_failure_count).toBe(1);
  });

  it('migrates a legacy current attempt on mutation without changing read-only inspection', async () => {
    const dispatched = await dispatchVerifier('receipt-legacy');
    const { verifier_action: _action, ...legacy } = dispatched.state;
    const file = nativePortableStateFile(paths, legacy.name);
    await writeNativePortableState(file, legacy);
    const before = await fs.readFile(file, 'utf8');
    const input = {
      kind: 'verifier-started' as const,
      candidateId: legacy.builder_handoff!.candidate_id,
      verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
    };
    await inspectNativePortableStatus({ paths, name: legacy.name });
    await validateNativeRunnerInputBoundary({
      paths,
      name: legacy.name,
      state: legacy,
      input,
      projectRoot: root,
    });
    expect(await fs.readFile(file, 'utf8')).toBe(before);
    const started = await applyNativeRunnerInput({
      paths,
      name: legacy.name,
      input,
      maxVerifyFailures: 5,
    });
    expect(started.state.verifier_action).toMatchObject({
      id: _action!.id,
      status: 'running',
      claim: { token: input.verifierExecutionRef },
    });
    expect((await readNativePortableState(file)).verifier_action).toEqual(
      started.state.verifier_action,
    );
  });

  it('keeps one active action while a Verifier requests Runtime checks', async () => {
    const dispatched = await dispatchVerifier('receipt-request-checks');
    const requested = await applyNativeRunnerInput({
      paths,
      name: dispatched.state.name,
      maxVerifyFailures: 5,
      input: {
        kind: 'verifier-response',
        candidateId: dispatched.state.builder_handoff!.candidate_id,
        verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
        response: {
          kind: 'request-checks',
          iteration: 1,
          attempt: 1,
          checks: [
            {
              id: 'probe',
              name: 'Probe',
              executable: process.execPath,
              argv: ['-e', 'process.exit(0)'],
              cwdRef: '.',
              timeoutMs: 10000,
              repeatable: true,
            },
          ],
        },
      },
    });
    expect(requested.state.verifier_action).toMatchObject({
      id: dispatched.state.verifier_action!.id,
      status: 'running',
      receipts: [],
    });
    expect(requested.state.verifier_action?.outcome).toBeUndefined();
    expect(requested.state.loop.next_action).toBe('await-verifier-result');
    expect(requested.checks).toMatchObject([{ id: 'probe', status: 'passed' }]);
  });

  it('marks a started action unknown after losing its machine metadata without redispatching', async () => {
    const dispatched = await dispatchVerifier('receipt-unknown');
    const file = path.join(root, 'startup.json');
    await fs.writeFile(
      file,
      JSON.stringify({
        kind: 'verifier-started',
        candidateId: dispatched.state.builder_handoff!.candidate_id,
        verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
      }),
    );
    const result = await runNativeCli([
      'next',
      dispatched.state.name,
      '--runner-input',
      file,
      '--project-root',
      root,
      '--json',
    ]);
    expect(result.exitCode).toBe(0);
    const state = await readNativePortableState(
      nativePortableStateFile(paths, dispatched.state.name),
    );
    expect(state.verifier_action?.status).toBe('running');
    await fs.unlink(nativeLocalExecutionFile(paths, state.name));
    const recovered = await recoverNativePortableChange({ paths, name: state.name });
    expect(recovered.state.verifier_action).toMatchObject({
      id: state.verifier_action!.id,
      status: 'unknown',
    });
    expect(recovered).toMatchObject({ action: 'await-user', reason: 'execution-active' });
    const repeated = await recoverNativePortableChange({ paths, name: state.name });
    expect(repeated.state.state_version).toBe(recovered.state.state_version);
    expect(repeated.state.loop.attempt).toBe(1);
  });

  it('accepts the same final outcome once and rejects a conflicting repeated outcome', async () => {
    const dispatched = await dispatchVerifier('receipt-terminal');
    const input = {
      kind: 'verifier-response' as const,
      candidateId: dispatched.state.builder_handoff!.candidate_id,
      verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
      response: {
        kind: 'final-result',
        result: {
          iteration: 1,
          attempt: 1,
          verdict: 'pass',
          acceptance: dispatched.state.acceptance.map(({ id }) => ({
            id,
            result: 'passed',
            reason: 'Inspected.',
          })),
          risks: [],
          summary: 'Verified.',
        },
      },
    };
    const first = await applyNativeRunnerInput({
      paths,
      name: 'receipt-terminal',
      input,
      maxVerifyFailures: 5,
    });
    expect(first.state.verifier_action?.status).toBe('succeeded');
    const repeated = await applyNativeRunnerInput({
      paths,
      name: 'receipt-terminal',
      input,
      maxVerifyFailures: 5,
    });
    expect(repeated.state.state_version).toBe(first.state.state_version);
    expect(repeated.state.verifier_action?.receipts).toHaveLength(1);
    const file = path.join(root, 'final-response.json');
    await fs.writeFile(file, JSON.stringify(input));
    const viaCli = await runNativeCli([
      'next',
      first.state.name,
      '--runner-input',
      file,
      '--project-root',
      root,
      '--json',
    ]);
    expect(viaCli.exitCode).toBe(0);
    expect(
      (await readNativePortableState(nativePortableStateFile(paths, first.state.name)))
        .state_version,
    ).toBe(first.state.state_version);
    await expect(
      applyNativeRunnerInput({
        paths,
        name: 'receipt-terminal',
        input: {
          ...input,
          response: {
            ...input.response,
            result: { ...input.response.result, summary: 'Different.' },
          },
        },
        maxVerifyFailures: 5,
      }),
    ).rejects.toThrow();
  });

  it('does not turn a delayed startup receipt into failure or another dispatch', async () => {
    const dispatched = await dispatchVerifier('receipt-delayed');
    vi.spyOn(Date, 'now').mockReturnValue(Date.now() + 2 * 60 * 60 * 1000);
    const status = await inspectNativePortableStatus({ paths, name: 'receipt-delayed' });
    expect(status.localExecution.verifierStartup).toMatchObject({
      confirmation: 'unconfirmed',
      waitingMinutes: 120,
    });
    expect(status.stateVersion).toBe(dispatched.state.state_version);
    expect(status.loop.attempt).toBe(dispatched.state.loop.attempt);
    expect(status.continuation).toMatchObject({
      action: 'await-verifier',
      disposition: 'continue',
      requiresUserDecision: false,
    });
    expect(status.continuation.userCommunication.agentInstruction).toContain(
      'A missing receipt alone does not prove failure',
    );
  });

  it('rejects startup receipts that are stale for the current attempt or candidate', async () => {
    const dispatched = await dispatchVerifier('receipt-stale');
    const candidateId = dispatched.state.builder_handoff!.candidate_id;

    await expect(
      applyNativeRunnerInput({
        paths,
        name: 'receipt-stale',
        input: {
          kind: 'verifier-started',
          candidateId,
          verifierExecutionRef: 'not-the-current-execution',
        },
        maxVerifyFailures: 5,
      }),
    ).rejects.toThrow(/stale|active/iu);

    await expect(
      applyNativeRunnerInput({
        paths,
        name: 'receipt-stale',
        input: {
          kind: 'verifier-started',
          candidateId: 'another-candidate',
          verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
        },
        maxVerifyFailures: 5,
      }),
    ).rejects.toThrow(/stale|active/iu);

    const status = await inspectNativePortableStatus({ paths, name: 'receipt-stale' });
    expect(status.localExecution.verifierStartup?.confirmation).toBe('unconfirmed');
  });

  it('parses exactly the verifier-started input shape', () => {
    expect(
      parseNativeRunnerInput({
        kind: 'verifier-started',
        candidateId: 'candidate',
        verifierExecutionRef: 'skill-coordinated:verifier:1',
      }),
    ).toEqual({
      kind: 'verifier-started',
      candidateId: 'candidate',
      verifierExecutionRef: 'skill-coordinated:verifier:1',
    });
    expect(() =>
      parseNativeRunnerInput({
        kind: 'verifier-started',
        candidateId: 'candidate',
        verifierExecutionRef: 'skill-coordinated:verifier:1',
        extra: true,
      }),
    ).toThrow();
    expect(() =>
      parseNativeRunnerInput({ kind: 'verifier-started', candidateId: 'candidate' }),
    ).toThrow();
  });

  it('surfaces the unconfirmed state in the human summary and recovery message', async () => {
    const dispatched = await dispatchVerifier('receipt-recovery');
    const envelopeRecord = (confirmation: 'unconfirmed' | 'confirmed') => ({
      continuation: {
        change: 'receipt-recovery',
        phase: 'verify',
        status: 'active',
        disposition: 'continue' as const,
        commandArgs: ['comet', 'native', 'next'],
        userCommunication: { required: false, message: null, agentInstruction: 'Keep waiting.' },
      },
      localExecution: { verifierStartup: { confirmation } },
    });
    expect(deriveNativeOutputEnvelope(envelopeRecord('unconfirmed'))?.summary).toContain(
      'has not confirmed startup',
    );
    expect(deriveNativeOutputEnvelope(envelopeRecord('confirmed'))?.summary).not.toContain(
      'has not confirmed startup',
    );

    const unconfirmed = await recoverNativePortableChange({
      paths,
      name: 'receipt-recovery',
    });
    expect(unconfirmed).toMatchObject({ action: 'await-user', reason: 'execution-active' });
    expect(unconfirmed.message).toContain('never confirmed startup');

    await applyNativeRunnerInput({
      paths,
      name: 'receipt-recovery',
      input: {
        kind: 'verifier-started',
        candidateId: dispatched.state.builder_handoff!.candidate_id,
        verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
      },
      maxVerifyFailures: 5,
    });
    const confirmed = await recoverNativePortableChange({
      paths,
      name: 'receipt-recovery',
    });
    expect(confirmed.message).not.toContain('never confirmed startup');
  });
});

import { fixtureAcceptanceReview } from '../../helpers/native-builder-acceptance-review.js';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import {
  defaultProjectConfig,
  writeProjectConfig,
} from '../../../domains/comet-native/native-config.js';
import { readNativeLocalExecution } from '../../../domains/comet-native/native-local-execution.js';
import {
  ensureNativeDirectories,
  nativePreferredChangeRuntimeDir,
  nativeProjectPaths,
} from '../../../domains/comet-native/native-paths.js';
import { archiveNativePortableChange } from '../../../domains/comet-native/native-portable-archive.js';
import {
  confirmNativePortableSkillCoordinatedPass,
  createNativePortableChange,
  dispatchNativePortableVerifier,
  executeNativePortableCheckPlan,
  nativeLocalExecutionFile,
  nativePortableChangeDir,
  readNativePortableChange,
  submitNativePortableBuilderCandidate,
  submitNativePortableVerifierResult,
} from '../../../domains/comet-native/native-portable-runtime.js';
import { confirmNativePortableShape } from '../../helpers/native-portable-confirmed-transition.js';
import { createNativeRunnerChannel } from '../../../domains/comet-native/native-runner-protocol.js';
import type { NativeProjectPaths } from '../../../domains/comet-native/native-types.js';

const FORBIDDEN_V4_ARTIFACT =
  /(?:^|[\\/_-])(snapshot|scope|receipt|evidence|trajectory|checkpoint)(?:$|[.\\/_-])/iu;

function passedReview(reviewerExecutionRef: string) {
  return {
    status: 'passed' as const,
    summary: 'Independent read-only review passed.',
    reviewerExecutionRef,
  };
}

describe('Native v4 verification-loop regression eval', () => {
  let root: string;
  let paths: NativeProjectPaths;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-v4-regression-'));
    await fs.mkdir(path.join(root, '.git'));
    await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
    paths = await nativeProjectPaths(root, 'docs');
    await ensureNativeDirectories(paths);
    await fs.writeFile(
      path.join(root, 'check-output.mjs'),
      `import { readFileSync, writeFileSync } from 'node:fs';

const [counterFile, label, sizeText] = process.argv.slice(2);
let counters = {};
try {
  counters = JSON.parse(readFileSync(counterFile, 'utf8'));
} catch (error) {
  if (error?.code !== 'ENOENT') throw error;
}
counters[label] = (counters[label] ?? 0) + 1;
writeFileSync(counterFile, JSON.stringify(counters));
const size = Number(sizeText);
process.stdout.write('o'.repeat(size));
process.stderr.write('e'.repeat(size));
`,
    );
  });

  afterEach(async () => {
    await fs.rm(root, { recursive: true, force: true });
  });

  async function expectNoLegacyVerificationArtifacts(): Promise<void> {
    const entries = (await fs.readdir(root, { recursive: true })).map(String);
    expect(entries.filter((entry) => FORBIDDEN_V4_ARTIFACT.test(entry))).toEqual([]);
  }

  async function readCounters(): Promise<Record<string, number>> {
    return JSON.parse(
      await fs.readFile(path.join(paths.workspaceRuntimeRoot, 'check-counts.json'), 'utf8'),
    ) as Record<string, number>;
  }

  function outputPlan(id: string, bytesPerStream: number) {
    return {
      id,
      name: `${id} output check`,
      executable: process.execPath,
      argv: [
        './check-output.mjs',
        path.join(paths.workspaceRuntimeRoot, 'check-counts.json'),
        id,
        String(bytesPerStream),
      ],
      cwdRef: '.',
      timeoutMs: 10_000,
      repeatable: true,
      reusable: true,
    };
  }

  it('requires independent full-coverage verification, loops repairs, and archives without legacy artifacts or rechecks', async () => {
    const name = 'portable-loop-eval';
    await createNativePortableChange({ paths, name, language: 'en' });
    const changeDir = nativePortableChangeDir(paths, name);
    await fs.writeFile(
      path.join(changeDir, 'brief.md'),
      `# Outcome
Ship a command whose output remains valid at every supported diagnostic size.

# Acceptance examples
- The command succeeds when stdout and stderr are both long.
- Archive preserves the independently verified result without rerunning checks.
`,
    );
    let state = await confirmNativePortableShape({ paths, name });
    expect(state.acceptance.map(({ id }) => id)).toEqual(['A1', 'A2']);
    await expectNoLegacyVerificationArtifacts();

    const runner = createNativeRunnerChannel();
    state = await submitNativePortableBuilderCandidate({
      paths,
      name,
      input: {
        identity: runner.captureExecutionIdentity({
          identityProvider: 'regression-host',
          executionRef: 'builder-confident-1',
        }),
        candidateId: 'candidate-1',
        summary: 'Everything is complete and all acceptance criteria pass.',
        addressedAcceptanceIds: ['A1', 'A2'],
        acceptanceReview: fixtureAcceptanceReview(['A1', 'A2']),
        checks: [{ name: 'Builder self-check', result: 'passed' }],
        review: passedReview('reviewer-confident-1'),
      },
    });

    expect(state).toMatchObject({
      phase: 'verify',
      verification_result: 'pending',
      verification: null,
      loop: { stage: 'verify-ready', iteration: 1, attempt: 0 },
    });
    await expect(archiveNativePortableChange({ paths, name })).rejects.toThrow('not archive-ready');

    const firstChecks = await executeNativePortableCheckPlan({
      paths,
      name,
      plans: [outputPlan('candidate-1-check', 0)],
    });
    await dispatchNativePortableVerifier({
      paths,
      name,
      checks: firstChecks.checks,
      verifierExecutionId: 'verifier-incomplete',
    });

    await expect(
      submitNativePortableVerifierResult({
        paths,
        name,
        checks: firstChecks.checks,
        maxVerifyFailures: 5,
        envelope: runner.envelopeVerifierResponse({
          candidateId: 'candidate-1',
          identity: runner.captureExecutionIdentity({
            identityProvider: 'regression-host',
            executionRef: 'verifier-incomplete',
          }),
          payload: {
            kind: 'final-result',
            result: {
              iteration: 1,
              attempt: 1,
              verdict: 'pass',
              acceptance: [{ id: 'A1', result: 'passed', reason: 'Observed the command succeed.' }],
              risks: [],
              summary: 'Pass claimed with incomplete coverage.',
            },
          },
        }),
      }),
    ).rejects.toThrow('missing: A2');
    state = await readNativePortableChange(paths, name);
    expect(state).toMatchObject({
      phase: 'verify',
      verification_result: 'pending',
      loop: {
        stage: 'verify-ready',
        next_action: 'await-verifier-result',
        execution_failure_count: 0,
      },
    });

    const failed = await submitNativePortableVerifierResult({
      paths,
      name,
      checks: firstChecks.checks,
      maxVerifyFailures: 5,
      envelope: runner.envelopeVerifierResponse({
        candidateId: 'candidate-1',
        identity: runner.captureExecutionIdentity({
          identityProvider: 'regression-host',
          executionRef: 'verifier-incomplete',
        }),
        payload: {
          kind: 'final-result',
          result: {
            iteration: 1,
            attempt: 1,
            verdict: 'fail',
            acceptance: [
              { id: 'A1', result: 'passed', reason: 'Long output completed.' },
              { id: 'A2', result: 'failed', reason: 'The Archive behavior still needs repair.' },
            ],
            risks: [],
            summary: 'One acceptance criterion remains unresolved.',
          },
        },
      }),
    });
    expect(failed.state).toMatchObject({
      phase: 'build',
      verification_result: 'fail',
      verification_report: 'verification.md',
      loop: { stage: 'repairing', iteration: 2, attempt: 0 },
    });
    await expect(
      fs.readFile(path.join(nativePortableChangeDir(paths, name), 'verification.md'), 'utf8'),
    ).resolves.toContain('Result: **Failed**');

    await submitNativePortableBuilderCandidate({
      paths,
      name,
      input: {
        identity: runner.captureExecutionIdentity({
          identityProvider: 'regression-host',
          executionRef: 'builder-repair-2',
        }),
        candidateId: 'candidate-2',
        summary: 'Repaired the Archive behavior reported by the independent Verifier.',
        addressedAcceptanceIds: ['A1', 'A2'],
        acceptanceReview: fixtureAcceptanceReview(['A1', 'A2']),
        review: passedReview('reviewer-repair-2'),
      },
    });
    const byteSizes = new Map([
      ['stdout-stderr-4k', 4 * 1024],
      ['stdout-stderr-64k', 64 * 1024],
      ['stdout-stderr-long', 256 * 1024],
    ]);
    const finalPlans = [...byteSizes].map(([id, size]) => outputPlan(id, size));
    const finalChecks = await executeNativePortableCheckPlan({
      paths,
      name,
      plans: finalPlans,
    });
    expect(finalChecks.checks).toHaveLength(3);
    expect(finalChecks.checks.every(({ status }) => status === 'passed')).toBe(true);

    const localBeforeArchive = await readNativeLocalExecution(
      nativeLocalExecutionFile(paths, name),
    );
    expect(localBeforeArchive?.execution).toMatchObject({
      stage: 'checking',
      actor: 'runtime',
      status: 'completed',
    });
    expect(
      localBeforeArchive?.checks.map(({ id, status, executionCount }) => ({
        id,
        status,
        executionCount,
      })),
    ).toEqual([...byteSizes.keys()].map((id) => ({ id, status: 'passed', executionCount: 1 })));
    for (const check of localBeforeArchive?.checks ?? []) {
      const bytesPerStream = byteSizes.get(check.id)!;
      const log = path.join(
        path.dirname(nativeLocalExecutionFile(paths, name)),
        ...check.log.split('/'),
      );
      expect((await fs.stat(log)).size).toBe(bytesPerStream * 2);
    }
    expect(await readCounters()).toEqual({
      'candidate-1-check': 1,
      'stdout-stderr-4k': 1,
      'stdout-stderr-64k': 1,
      'stdout-stderr-long': 1,
    });
    const reusedChecks = await executeNativePortableCheckPlan({ paths, name, plans: finalPlans });
    expect(reusedChecks.checks.map(({ id, status }) => ({ id, status }))).toEqual(
      finalChecks.checks.map(({ id, status }) => ({ id, status })),
    );
    expect(await readCounters()).toEqual({
      'candidate-1-check': 1,
      'stdout-stderr-4k': 1,
      'stdout-stderr-64k': 1,
      'stdout-stderr-long': 1,
    });

    await dispatchNativePortableVerifier({
      paths,
      name,
      checks: finalChecks.checks,
      verifierExecutionId: 'verifier-complete',
    });
    const passed = await submitNativePortableVerifierResult({
      paths,
      name,
      checks: finalChecks.checks,
      maxVerifyFailures: 5,
      envelope: runner.envelopeVerifierResponse({
        candidateId: 'candidate-2',
        identity: runner.captureExecutionIdentity({
          identityProvider: 'regression-host',
          executionRef: 'verifier-complete',
        }),
        payload: {
          kind: 'final-result',
          result: {
            iteration: 2,
            attempt: 1,
            verdict: 'pass',
            acceptance: [
              { id: 'A1', result: 'passed', reason: 'All three long-output checks passed.' },
              { id: 'A2', result: 'passed', reason: 'Archive no longer reruns verification.' },
            ],
            risks: [],
            summary: 'Every acceptance criterion and Runtime-owned check passed.',
          },
        },
      }),
    });
    expect(passed.state).toMatchObject({
      phase: 'verify',
      status: 'await-user',
      verification_result: 'pass',
      loop: {
        stage: 'await-user',
        iteration: 2,
        attempt: 1,
        next_action: 'confirm-skill-coordinated-pass',
      },
    });
    expect(
      passed.state.verification?.checks.map(({ id, duration_ms }) => ({ id, duration_ms })),
    ).toEqual(finalChecks.checks.map(({ id, duration_ms }) => ({ id, duration_ms })));
    await expectNoLegacyVerificationArtifacts();

    const confirmed = await confirmNativePortableSkillCoordinatedPass({ paths, name });
    expect(confirmed).toMatchObject({
      phase: 'archive',
      loop: { stage: 'archive-ready', iteration: 2, attempt: 1 },
    });

    const countsBeforeArchive = await readCounters();
    const archived = await archiveNativePortableChange({ paths, name });
    expect(await readCounters()).toEqual(countsBeforeArchive);
    expect((await fs.readdir(archived.archiveDir)).sort()).toEqual([
      'brief.md',
      'comet-state.yaml',
      'specs',
      'verification.md',
    ]);
    await expect(fs.stat(nativePreferredChangeRuntimeDir(paths, name))).rejects.toMatchObject({
      code: 'ENOENT',
    });
    await expectNoLegacyVerificationArtifacts();
  });
});
